def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != bg and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            objects.append(cells)
    if not objects:
        return []
    height = max(max(y for y, x in obj) - min(y for y, x in obj) + 1 for obj in objects)
    width = max(max(x for y, x in obj) - min(x for y, x in obj) + 1 for obj in objects)
    base = Counter(grid[y][x] for obj in objects for y, x in obj).most_common(1)[0][0]
    out = [[base] * width for _ in range(height)]
    for obj in objects:
        top = min(y for y, x in obj)
        left = min(x for y, x in obj)
        for y, x in obj:
            if grid[y][x] != base:
                out[y - top][x - left] = grid[y][x]
    return out
